DELETE FROM CUMULATIVE_EXEC_TIME WHERE TABLE_ID=1;
DELETE FROM CUMULATIVE_EXEC_TIME WHERE TABLE_ID=2;

DELETE FROM cumulation_table WHERE TABLE_ID=1;
DELETE FROM cumulation_table WHERE TABLE_ID=2;

INSERT INTO cumulation_table
(cumulation_table_name, evr_table_name, cumulation_columns, evr_table_type, table_id, db_user, db_pswd, db_ip, db_name, db_srv, select_query)
VALUES('IVR_MIS_CUMULATIVE', 'IVR_EVR_DETAILS', 'COUNT', 'D', 2, '<DB_USERNAME>', '<DB_PASSWORD>', '<DB_IP>', '<DB_NAME>', 'public', 'SELECT DATE_TRUNC(''hour'', GEN_TIME) AS GEN_TIME, evr_event AS EVR_EVENT, evr_cause AS EVR_CAUSE, evr_cause AS EVR_REASON, SHORT_CODE, COUNT(*) AS COUNT, SUM(DURATION) AS DURATION FROM <:EVR_TABLE> WHERE gen_time BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') GROUP BY  DATE_TRUNC(''hour'', GEN_TIME), evr_event, evr_cause, evr_reason, SHORT_CODE LIMIT 200');

INSERT INTO cumulation_table
(cumulation_table_name, evr_table_name, cumulation_columns, evr_table_type, table_id, db_user, db_pswd, db_ip, db_name, db_srv, select_query)
VALUES('IVR_MIS_CONTENT_CUMULATIVE', 'IVR_EVR_DETAILS', 'TOT_INCOMING_CALL_RECEIVED,TOT_INCOMING_CALL_ANSWERED,TOT_INCOMING_CALL_DISCONNECTED,TOT_INCOMING_CALL_COMPLETED,TOT_INCOMING_CALL_REJECTED', 'D', 1, '<DB_USERNAME>','<DB_PASSWORD>','<DB_IP>','<DB_NAME>', 'public', 'SELECT DATE_TRUNC(''hour'', GEN_TIME) AS GEN_DATE, HOUR(GEN_TIME) AS GEN_HOUR, SHORT_CODE, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 1 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_RECEIVED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 3 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_ANSWERED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 4 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_DISCONNECTED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 13 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_COMPLETED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 5 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_REJECTED FROM <:EVR_TABLE> WHERE GEN_TIME BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') GROUP BY DATE_TRUNC(''hour'', GEN_TIME), HOUR(GEN_TIME), SHORT_CODE');

INSERT INTO CUMULATIVE_EXEC_TIME(TABLE_ID,TIME) VALUES(1, '<DATE_WITH_yyyy-mm-dd HH24:mi:ss.000>');
INSERT INTO CUMULATIVE_EXEC_TIME(TABLE_ID,TIME) VALUES(2, '<DATE_WITH_yyyy-mm-dd HH24:mi:ss.000>');

COMMIT;

